def number_existing_articles(apps, schema_editor):
    """Give each issue's articles an order matching the one they showed before.

    Until now an issue was listed by first page, then title, so that is the
    order kept — nothing on a published contents page moves.
    """
    Article = apps.get_model('journal', 'Article')
    issue_ids = (
        Article.objects.exclude(issue__isnull=True)
        .values_list('issue_id', flat=True).distinct()
    )
    for issue_id in issue_ids:
        articles = sorted(
            Article.objects.filter(issue_id=issue_id),
            key=lambda a: (a.first_page is None, a.first_page or 0, a.title),
        )
        for position, article in enumerate(articles, start=1):
            Article.objects.filter(pk=article.pk).update(issue_order=position)


def keep_page_numbers_already_entered(apps, schema_editor):
    """An issue whose page numbers were typed in by hand keeps them.

    Those numbers may be what a printed copy says and what has been cited. An
    editor can still tick 'paginate automatically' to have them worked out.
    """
    Issue = apps.get_model('journal', 'Issue')
    Issue.objects.filter(articles__first_page__isnull=False).update(paginate_automatically=False)


